import { Dispatch, SetStateAction } from "react";

type ButtonType = "Create" | "Join";

interface ButtonProps {
  type: ButtonType;
  setIsOpenModal: Dispatch<SetStateAction<boolean>>;
}

export default function Button({ type, setIsOpenModal }: ButtonProps) {
  return (
    <button
      onClick={() => setIsOpenModal(true)}
      className={`p-2 mt-5 w-50 rounded-[10px] cursor-pointer ${type === "Create" ? "bg-white text-black" : "border border-gray-500"}`}
    >
      {type === "Create" ? "Создать комнату" : "Войти по коду"}
    </button>
  );
}
